def keyExpansion(key,roundConst):

    # hex_2D_array=Convert_to_2D_Array_of_Hex(key)
    
    for iterator in range(1,NumberofRounds):
        w=[]
        for i in range (0,matrixOrder):
            w.append(key[8*i:8*i+8])
    
        #circular byte left shift of w3

        w3=BitVector(hexstring=w[3])
        w3<<8
        w3InHex=w3.get_bitvector_in_hex()
    
        
        g_w3=""
        i=0
        #Byte substitution from S-box and round const
        while i<len(w3InHex):
            b = BitVector(hexstring=w3InHex[i]+w3InHex[i+1])
            int_val = b.intValue()
            s = Sbox[int_val]
            s = BitVector(intVal=s, size=8)
            if i==0 :
                s=s^BitVector(hexstring=roundConst)
            g_w3+=s.get_bitvector_in_hex()
            i+=2

        
        newKey=[]
        newKey.append((BitVector(hexstring=w[0])^BitVector(hexstring=g_w3)).get_bitvector_in_hex())
        for i in range (1,len(w)):
            newKey.append((BitVector(hexstring=w[i])^BitVector(hexstring=newKey[i-1])).get_bitvector_in_hex())
        
        
        key=""
        for i in range (0,len(newKey)):
            key+=newKey[i]

        Roundkeys.append(key)
       
        
        if ((BitVector(hexstring=roundConst)).intValue()>= (BitVector(hexstring="80")).intValue()) :
            const=BitVector(hexstring=roundConst)
            const.shift_left(1)   
            # print(const)
            
            roundConst= BitVector(intVal=((const^AES_modulus) & BitVector(hexstring=("FF"))).intValue(),size=8).get_bitvector_in_hex()
            

        else :
            const=BitVector(hexstring=roundConst)
            const.shift_left(1)   
            roundConst=const.get_bitvector_in_hex()
           
        
        
        
    
    0


def Convert_to_2D_Array_of_Hex(hexstring):
    
    hex_2D_array=[]

    for i in range(0,matrixOrder):
        hex_2D_array.append([])
    i=0
    j=0
    while i<len(hexstring):
        eachelement=""
        eachelement+=hexstring[i]
        eachelement+=hexstring[i+1]
        # print(eachelement)
        i+=2
        hex_2D_array[j].append(eachelement)
        j=(j+1)%matrixOrder
        # print(j)
    
    # for i in range (0,4):
    #     for j in range (0,4):
    #         sys.stdout.write(hex_2D_array[i][j]+" ")
    #     print()
    
    return hex_2D_array



def LastBlockPadding(Block):
    print(Block)
    length=(32-len(Block))/2
    print(length)
    for i in range (int(length)):            #convert to int otherwise segmentation fault because length was float type
        Block+=BitVector(intVal=int(length),size=8).get_bitvector_in_hex()
    
    
    return Block

        
def KeyPadding(key):

    bitSize=4*len(key)

    if(bitSize != KEY_LEN):
          while bitSize < KEY_LEN :
               key+=format(ord(" "), "x")
               bitSize+=8
    return key
    


def convertStringToHex(stringValue):
    hexstring=""
    for i in range(0,len(stringValue)):
        hexstring+=format(ord(stringValue[i]), "x")
    return hexstring

def convertHexToString(hexValue):
    bytes_obj = bytes.fromhex(hexValue)
    result_string = bytes_obj.decode('utf-8')
    return result_string

    
def substitutionByte(Msg2DInHex):
    for i in range (0,matrixOrder):
        for j in range (0,matrixOrder):
            b = BitVector(hexstring=Msg2DInHex[i][j])
            int_val = b.intValue()
            s = Sbox[int_val]
            s = BitVector(intVal=s, size=8)
            Msg2DInHex[i][j]=s.get_bitvector_in_hex()
    return Msg2DInHex

def InversesubstitutionByte(cipher2DInHex):
    for i in range (0,matrixOrder):
        for j in range (0,matrixOrder):
            b = BitVector(hexstring=cipher2DInHex[i][j])
            int_val = b.intValue()
            s = InvSbox[int_val]
            s = BitVector(intVal=s, size=8)
            cipher2DInHex[i][j]=s.get_bitvector_in_hex()
    return cipher2DInHex

def ShiftRow(Msg2DInHex):
    temp=[]
    for i in range (0,matrixOrder):
        temp.append([])
        for j in range (0,matrixOrder):
            temp[i].append(" ")
    for i in range (0,matrixOrder):
        for j in range (0,matrixOrder):
            index=(j+matrixOrder-i)%matrixOrder
            temp[i][index]=Msg2DInHex[i][j]
    # print(temp)    
    return temp 


def InverseShiftRow(cipher2DInHex):
    temp=[]
    for i in range (0,matrixOrder):
        temp.append([])
        for j in range (0,matrixOrder):
            temp[i].append(" ")
    for i in range (0,matrixOrder):
        for j in range (0,matrixOrder):
            index=(j+i)%matrixOrder
            temp[i][index]=cipher2DInHex[i][j]
    # print(temp)    
    return temp


def MixColumn(Msg2DInHex):
    temp=[]
    for i in range (0,matrixOrder):
        temp.append([])
        for j in range (0,matrixOrder):
            temp[i].append("00")

    for i in range(matrixOrder):
        for j in range(matrixOrder):
            for k in range(matrixOrder):
                # result[i][j] += X[i][k] * Y[k][j]
                result = Mixer[i][k].gf_multiply_modular(BitVector(hexstring=Msg2DInHex[k][j]), AES_modulus, 8)
                temp[i][j]=(BitVector(hexstring=temp[i][j])^result).get_bitvector_in_hex()

    return temp
                        
def InverseMixColumn(Cipher2DInHex):
    temp=[]
    for i in range (0,matrixOrder):
        temp.append([])
        for j in range (0,matrixOrder):
            temp[i].append("00")

    for i in range(matrixOrder):
        for j in range(matrixOrder):
            for k in range(matrixOrder):
                # result[i][j] += X[i][k] * Y[k][j]
                result = InvMixer[i][k].gf_multiply_modular(BitVector(hexstring=Cipher2DInHex[k][j]), AES_modulus, 8)
                temp[i][j]=(BitVector(hexstring=temp[i][j])^result).get_bitvector_in_hex()

    return temp


def AddRoundkey(Msg2DInHex,Roundkey):

    hex_2D_key=Convert_to_2D_Array_of_Hex(Roundkey)

    for i in range (0,matrixOrder):
        for j in range (0,matrixOrder):
            Msg2DInHex[i][j]=(BitVector(hexstring=Msg2DInHex[i][j]) ^ BitVector(hexstring=hex_2D_key[i][j])).get_bitvector_in_hex()
    return Msg2DInHex

def AES_encryption(Msg2DInHex):

    for i in range(0,NumberofRounds):
        if i!=0 :
            Msg2DInHex=substitutionByte(Msg2DInHex)
            Msg2DInHex=ShiftRow(Msg2DInHex)
        if i!=0 and i!=(NumberofRounds-1) :
            Msg2DInHex=MixColumn(Msg2DInHex)
        Msg2DInHex=AddRoundkey(Msg2DInHex,Roundkeys[i])

    return Msg2DInHex

def AES_decryption(Cipher2DInHex):
    i=NumberofRounds-1
    while i >=0 :
        if i!=(NumberofRounds-1):
            Cipher2DInHex=InverseShiftRow(Cipher2DInHex)
            Cipher2DInHex=InversesubstitutionByte(Cipher2DInHex)
        Cipher2DInHex=AddRoundkey(Cipher2DInHex,Roundkeys[i])  
        if i!=0 and i!=(NumberofRounds-1) :
            Cipher2DInHex=InverseMixColumn(Cipher2DInHex)
        i-=1
        

    return Cipher2DInHex

def SplitingInBlocks(plaintext):

    Blocks=[]
    

    i=0
    while i < len(plaintext) :
        j=i
        temp=""
        while j < (i+32) and j < len(plaintext) :
            temp+=plaintext[j]
            j+=1
        Blocks.append(temp)
        i+=32
    return Blocks
    





